  W.a126 = { "match": "Spotify Track Card", "core": 3, "brand": { "name": "Spotify", "color": "#1DB954", "head": "#121212", "ink": "#ffffff", "team": "Content Platform", "font": "800 22px 'Segoe UI',Helvetica,Arial,sans-serif", "spacing": "-0.5px" }, "boss": { "name": "Priya Nair", "title": "Senior Backend Engineer", "initials": "PN" }, "ticket": "CP-1042", "file": "track_card.py", "email": { "subject": "Track card for Blinding Lights (needed before tomorrow's demo)", "paras": [ "Hi, and welcome to the Content Platform team! I'm glad you're here.", "Every song in the app has an info card, and the code behind the card keeps each fact in a variable. The Charts team is demoing tomorrow with **Blinding Lights**, and the card script still isn't done. Can you build it, and then make it keep the play count up to date?", "The facts are in `track_data.txt`. Please follow the naming rules in `style_guide.md`: our review bot bounces anything that breaks them, and I'd rather not be the one who bounces yours.", "Work through the steps below in order. When you have a version that runs, click **Send to Priya** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Priya" }, "files": [ { "name": "track_data.txt", "text": "title:       Blinding Lights\nartist:      The Weeknd\nplays:       4,000,000\nlength:      200 seconds\nrating:      4.8\n\ncharts #1:   Flowers\ncharts #2:   As It Was\n\nSTRETCH TASKS\n  wrapped: three more plays\n  up next: Levitating by Dua Lipa" }, { "name": "style_guide.md", "text": "BACKEND STYLE GUIDE (excerpt)\n\nVariable names\n  - lowercase words joined by underscores\n  - describe what the variable holds\n  - never start with a number\n  - no spaces and no dashes\n  - never reuse a word Python already owns (class, if, for, and so on)\n  - capital letters count: Play_Count and play_count are two different variables\n\nFiles\n  - start with a comment that says what the file is for\n  - print the variable, never a typed-in copy of its value" } ], "review": { "open": "Thanks for sending this over. I read through your track card script.", "stages": [ { "ok": "The file starts with a clear purpose, the names follow our style guide, and all seven facts are stored. Clean and readable.", "todo": "The setup isn't finished yet. I need the purpose and name rules comments and the seven variables with the exact names, holding the right kind of value." }, { "ok": "The card prints every fact with its label, straight from the variables. That's what I wanted.", "todo": "The card isn't printing right yet. Check each label, and print the variable, not a typed copy." }, { "ok": "You updated the same play_count variable when the listener pressed play instead of making a new one. Good instinct.", "todo": "The play count isn't updating the way I asked. It should change the same variable by one, then print PLAYS NOW." }, { "ok": "The Wrapped counter works, and your comment shows you understand why we reuse one variable.", "todo": "Stretch: the Wrapped counter isn't done yet. It's optional." }, { "ok": "The Up Next row is a real improvement. Thank you for the extra.", "todo": "Stretch: the Up Next row isn't done yet. Also optional." } ], "approve": "That's everything I asked for. The card is ready for the demo.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "I'm putting you down for the Charts demo prep next week. Great work.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a127 = { "match": "Apple Battery Health", "core": 4, "brand": { "name": "Apple", "color": "#0071E3", "head": "#F5F5F7", "ink": "#1D1D1F", "team": "Settings Engineering", "font": "600 22px 'Helvetica Neue',Helvetica,Arial,sans-serif", "spacing": "0" }, "boss": { "name": "Marcus Lee", "title": "Settings Engineering Manager", "initials": "ML" }, "ticket": "SET-3318", "file": "battery_page.py", "email": { "subject": "Battery page data types (QA wants proof before Friday)", "paras": [ "Hi, thanks for picking this up.", "The Battery page in Settings shows a handful of facts that are all different kinds of data: a model name, a cycle count, a health percentage, a charging flag and the zip code of the store that serviced the phone. QA found that a past build stored one of them as the wrong type, and I'd like proof that this version gets every one right.", "The sample values are in `battery_spec.txt`. Please store each fact, print its type for QA, add the service rules, and handle the sensor failure case in the steps below.", "Work through the steps below in order. When you have a version that runs, click **Send to Marcus** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Marcus" }, "files": [ { "name": "battery_spec.txt", "text": "BATTERY PAGE FACTS\n\nmodel_name       text      iPhone 15\nbattery_cycles   whole     312\nbattery_health   decimal   91.5   (percent)\nis_charging      yes/no    True\nzip_code         30326 (Lenox Square store)\n\nRULES\n  Battery OK    when health is at least 80\n  Heavy use     at 500 cycles or more\n\nSENSOR FAILURE\n  the cycle count is replaced by the text: Unknown\n\nSTRETCH TASKS\n  storage: 128 GB total, 31.5 GB free\n  a repair estimate: 79.0 per part, 2 parts" }, { "name": "qa_notes.md", "text": "QA NOTES\n\n- a zip code is not a number you do math with, so it is stored as text\n- every fact must print its type so we can check it\n- do not type True or False for a rule: compare the numbers and let the program decide" } ], "review": { "open": "Thanks, I read through the Battery page script.", "stages": [ { "ok": "All five facts are stored as the right kinds of values, including the zip code as text. That's the foundation of the page.", "todo": "The facts aren't all stored with the right types yet: text, whole number, decimal, True or False, and the zip code as text." }, { "ok": "The type printout gives QA exactly the proof they asked for.", "todo": "QA still needs the type of all five printed, one line each." }, { "ok": "Both service rules are calculated by comparing the numbers, not typed in. That's the correct approach.", "todo": "The service rules aren't right yet. Compare the numbers and let Python decide; don't type True or False." }, { "ok": "You changed the same variable to Unknown and printed its new type. That's what happens when the sensor fails, and you handled it.", "todo": "The sensor failure case isn't done yet: change the same variable and print its type." }, { "ok": "The storage check works. Thanks for going beyond the ticket.", "todo": "Stretch: the storage check isn't done yet. Optional." }, { "ok": "The repair estimate is clear, and your note about decimals and whole numbers is correct.", "todo": "Stretch: the repair estimate isn't done yet. Also optional." } ], "approve": "Everything on the ticket is done and QA can sign off.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "This is above and beyond what I asked for. I'll mention it in the team update.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a128 = { "match": "Chick-fil-A Mobile Order", "core": 3, "brand": { "name": "Chick-fil-A", "color": "#E51636", "head": "#E51636", "ink": "#ffffff", "team": "Mobile Ordering", "font": "italic 800 24px Georgia,'Times New Roman',serif", "spacing": "-0.5px" }, "boss": { "name": "Daniel Brooks", "title": "Mobile Ordering Engineering Lead", "initials": "DB" }, "ticket": "MOB-2210", "file": "order_screen.py", "email": { "subject": "Mobile order screen: kitchen ticket prototype (needed before the lunch-rush test)", "paras": [ "Hi, and welcome to Mobile Ordering! It's good to have another set of hands before the lunch-rush test.", "When a customer places an order in the app, the screen asks a few questions and the kitchen ticket prints. One thing trips everybody up: what the customer types arrives as **text**, even when they type digits.", "The sample orders are in `sample_orders.txt`, and `ticket_format.md` shows how the kitchen wants the ticket to look.", "Work through the steps below in order. When you have a version that runs, click **Send to Daniel** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Daniel" }, "files": [ { "name": "sample_orders.txt", "text": "SAMPLE MOBILE ORDERS\n\nname     sandwich         pickup minutes   sauce codes\nMaria    spicy chicken    10               12 and 34\nDevon    nuggets          25               07 and 21\n\nSTRETCH TASKS\n  read the order back in one sentence\n  a rewards code from the name and both sauce codes" }, { "name": "ticket_format.md", "text": "KITCHEN TICKET FORMAT\n\n  KITCHEN TICKET\n  ORDER FOR <name>\n  SANDWICH <sandwich>\n  PICKUP MINUTES <minutes>\n  PICKUP TYPE <what kind of value the app received>\n  TICKET CODE <sauce code 1 followed by sauce code 2>\n\nNOTE\n  every label and every value is on its own line" } ], "review": { "open": "Thanks for sending this over. I ran the order screen with a few test orders.", "stages": [ { "ok": "The five questions are all there and every answer is stored.", "todo": "The questions aren't all there yet: five answers, each in its own variable." }, { "ok": "The ticket prints every line, and the type line shows the kitchen what the app really receives.", "todo": "The ticket isn't printing right yet. Check each label and the type of the pickup time." }, { "ok": "The ticket code sticks the two sauce codes together instead of adding them. That's exactly what the kitchen needs.", "todo": "The ticket code isn't right yet. The kitchen wants the two codes stuck together." }, { "ok": "The read-back sentence works.", "todo": "Stretch: the read-back sentence isn't done yet. It's optional." }, { "ok": "The rewards code works, and your note shows you understand why digits stick together.", "todo": "Stretch: the rewards code isn't done yet. Also optional." } ], "approve": "Everything on the ticket works and the kitchen can use it.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "You even did the stretch work. I'm adding you to the lunch-rush test.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a129 = { "match": "Steam Purchase Receipt", "core": 3, "brand": { "name": "STEAM", "color": "#1B6FA8", "head": "#171A21", "ink": "#C7D5E0", "team": "Store Engineering", "font": "800 22px 'Segoe UI',Arial,sans-serif", "spacing": "3px" }, "boss": { "name": "Jordan Wells", "title": "Store Platform Engineer", "initials": "JW" }, "ticket": "STORE-5081", "file": "receipt.py", "email": { "subject": "Purchase receipt: the text-and-numbers one", "paras": [ "Hi! Thanks for helping on the Store team.", "After every purchase Steam prints a receipt, and each line mixes words with numbers: the game title, the price, how many copies, whether it is a gift. Our last receipt script crashed on a number that was joined to some text, and a customer saw a raw error. I need a version that never does that.", "The purchase for testing is in `test_purchase.txt`, and `receipt_layout.md` has the exact look of every line.", "Work through the steps below in order. When you have a version that runs, click **Send to Jordan** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Jordan" }, "files": [ { "name": "test_purchase.txt", "text": "TEST PURCHASE\n\ngame_title   Portal 2\nprice        9.99\ncopies       2\nis_gift      True\n\nSTRETCH TASKS\n  sale banner: 3 games on sale at 50 percent\n  total due, shown as text" }, { "name": "receipt_layout.md", "text": "RECEIPT LAYOUT\n\n  ==========\n  Game: <title>\n  Price: $<price>\n  Copies: <copies>\n  Gift: <True or False>\n  Total: <price times copies>\n  ==========\n\nHOUSE RULES\n  - the divider is ten equal signs\n  - each of the four middle lines is one single piece of text\n  - the total line uses commas, like the rest of our logs" } ], "review": { "open": "Thanks, I ran your receipt script against the test purchase.", "stages": [ { "ok": "The four purchase facts are stored with the right kinds of values.", "todo": "The purchase facts aren't all stored yet. Check the title, price, copies and gift flag." }, { "ok": "The divider is built by repeating one character, and every receipt line is one joined piece of text with no crashes. That's the bug that hit us last time, fixed.", "todo": "Some receipt lines still mix a number with text, which is the crash we had before. Convert first, and check the divider." }, { "ok": "The total comes out right, 19.98 for two copies, and the receipt closes with the divider.", "todo": "The Total line or the closing divider isn't right yet." }, { "ok": "The sale banner and the row of stars look great.", "todo": "Stretch: the sale banner isn't done yet. It's optional." }, { "ok": "The total-due line works, and your note explains the crash perfectly.", "todo": "Stretch: the total-due line isn't done yet. Also optional." } ], "approve": "The receipt prints correctly and can't crash on a number any more.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "That's the whole receipt plus the sale banner. I'll slot it into the next Store release.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a130 = { "match": "TikTok Username Badge", "core": 4, "brand": { "name": "TikTok", "color": "#FE2C55", "head": "#010101", "ink": "#ffffff", "team": "Creator Onboarding", "font": "900 24px 'Helvetica Neue',Arial,sans-serif", "spacing": "-1px" }, "boss": { "name": "Zoe Kim", "title": "Onboarding Engineer", "initials": "ZK" }, "ticket": "ONB-7740", "file": "badge.py", "email": { "subject": "Username badge for new creators (needed for tomorrow's sign-up test)", "paras": [ "Hi, and welcome to Creator Onboarding!", "When a new creator picks a username, the sign-up screen builds a little badge from specific characters in the name. Everything depends on counting positions correctly, and our last intern's code crashed on an off-by-one. Please build this one carefully.", "`badge_rules.txt` says what the badge shows, and `test_names.txt` has the names we test with.", "Work through the steps below in order. When you have a version that runs, click **Send to Zoe** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Zoe" }, "files": [ { "name": "badge_rules.txt", "text": "BADGE RULES\n\n  LENGTH            how many characters are in the name\n  FIRST and LAST    the first character and the last character\n  MIDDLE            the character in the middle of the name\n  THIRD             the third character\n  SECOND TO LAST    the character before the last one\n  LAST INDEX        the highest position that exists in the name\n\nSTRETCH TASKS\n  BADGE   first and last characters together\n  STARS   one star for every character in the name" }, { "name": "test_names.txt", "text": "TEST NAMES\n\n  creator    (7 characters, the main test)\n  tiktoker  (8 characters)\n  zoe       (3 characters)\n\nThe sign-up box asks: Pick a username:" } ], "review": { "open": "Thanks, I tried your badge code with the test names.", "stages": [ { "ok": "The name comes from the sign-up box and the length is right.", "todo": "The first step isn't working yet: ask for the username and print its length." }, { "ok": "First and last characters are correct, and counting from the end means it works for any name.", "todo": "The first and last characters aren't right yet. Count from the end to get the last one." }, { "ok": "The middle is worked out from the length, and third and second to last are correct. You're counting positions properly.", "todo": "The middle, third or second-to-last character isn't right yet. Remember the first position is 0." }, { "ok": "The last index is one less than the length, and your IMMUTABLE note shows you understand why strings can't be edited in place.", "todo": "The last index and the IMMUTABLE comment aren't done yet." }, { "ok": "The badge and the star row work, and both are built from the name instead of typed.", "todo": "Stretch: the initials badge and the star row aren't done yet. It's optional." }, { "ok": "Counting from both ends works, and your note about position 7 is correct.", "todo": "Stretch: counting from both ends isn't done yet. Also optional." } ], "approve": "The badge matches every rule and the name check is solid.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "You did the stretch tasks too. I'll use your badge for the sign-up test.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a131 = { "match": "Airbnb Confirmation Codes", "core": 3, "brand": { "name": "airbnb", "color": "#E0383E", "head": "#ffffff", "ink": "#FF385C", "team": "Reservations", "font": "800 26px 'Helvetica Neue',Helvetica,Arial,sans-serif", "spacing": "-1px" }, "boss": { "name": "Luis Moreno", "title": "Reservations Engineer", "initials": "LM" }, "ticket": "RES-3305", "file": "confirmation.py", "email": { "subject": "Reading a confirmation code (host texts go out tonight)", "paras": [ "Hi, thanks for taking this on.", "Every booking has a confirmation code, and every piece of the code means something: the airport, the date, who booked. Hosts get text messages built from those pieces, and the guest's phone number gets split up the same way. I need the code cut up correctly.", "The booking is in `booking.txt`, and `code_format.md` explains what each part of the code means.", "Work through the steps below in order. When you have a version that runs, click **Send to Luis** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Luis" }, "files": [ { "name": "booking.txt", "text": "BOOKING\n\nconfirmation   ATL20261125GUEST\nphone          7705551234   (text, not a number)\n\nSTRETCH TASKS\n  guest tag: the last five characters, a dash, then the first three\n  masked phone: six stars, then the last four digits\n  month and day printed separately" }, { "name": "code_format.md", "text": "CONFIRMATION CODE FORMAT (16 characters)\n\n  characters 1 to 3     airport code\n  characters 4 to 7     year\n  characters 8 to 11    month and day (two digits and two digits)\n  the last 5            who booked\n\nPHONE NUMBER\n  area code (3), prefix (3), line number (4)\n\nTEXT PREVIEW\n  the first 8 characters of the code, followed by three dots" } ], "review": { "open": "Thanks, I ran your confirmation code script on the booking.", "stages": [ { "ok": "Airport, year, and month and day are all cut out correctly.", "todo": "One of the airport, year, or month-and-day pieces isn't right yet. Check where each piece starts and stops." }, { "ok": "Counting from the end works: Booked by and Code only are both right.", "todo": "The pieces counted from the end aren't right yet." }, { "ok": "The phone number is split into area code, prefix and line number, and the preview is ready for the text message.", "todo": "The phone number split or the text preview isn't right yet." }, { "ok": "The guest tag and the masked phone are a nice privacy touch.", "todo": "Stretch: the guest tag and masked phone aren't done yet. It's optional." }, { "ok": "Month and day are separated and your SLICE note is exactly right.", "todo": "Stretch: the month and day part isn't done yet. Also optional." } ], "approve": "Every piece of the code is cut out correctly.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The extras will help our support team. Thanks for going the extra mile.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a132 = { "match": "Gmail Address Splitter", "core": 3, "brand": { "name": "Gmail", "color": "#D93025", "head": "#ffffff", "ink": "#D93025", "team": "Account Creation", "font": "800 24px 'Google Sans',Arial,sans-serif", "spacing": "0" }, "boss": { "name": "Anika Rao", "title": "Account Creation Engineer", "initials": "AR" }, "ticket": "ACC-9120", "file": "address_split.py", "email": { "subject": "Splitting an email address (sign-up form fix)", "paras": [ "Hi, welcome to Account Creation!", "On the sign-up form people type their email address, and our checker has to find the @ sign and split the address into the name part and the website part. When someone forgets the @, the checker has to notice that too instead of guessing.", "`addresses.txt` has the addresses we test with, and `split_rules.md` has the output we want.", "Work through the steps below in order. When you have a version that runs, click **Send to Anika** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Anika" }, "files": [ { "name": "addresses.txt", "text": "TEST ADDRESSES\n\n  ava.smith@gmail.com     (the main test, typed in by the tester)\n  ava.smith.gmail.com     (forgot the @)\n\nSTRETCH TASKS\n  name length and the extension after the dot\n  a True or False check for each address: does it contain an @?" }, { "name": "split_rules.md", "text": "SPLIT RULES\n\n  At position:      where the @ sits\n  Username:         everything before the @\n  Domain:           everything after the @\n  Provider:         the part of the domain before its first dot\n  Bad email position:  what the search says when the @ is missing\n  Gmail starts at:  where the word gmail begins in the whole address" } ], "review": { "open": "Thanks, I ran your splitter on the test addresses.", "stages": [ { "ok": "The @ is found by Python and not counted by hand.", "todo": "The @ isn't found yet. Ask for the email and let Python find the position." }, { "ok": "Username, domain and provider are split cleanly around the @ and the dot.", "todo": "The split isn't right yet. The domain starts just after the @, and the provider ends at the first dot." }, { "ok": "You showed what happens with a missing @ and found where gmail starts, exactly the cases we worried about.", "todo": "The missing-@ case or the search for gmail isn't done yet." }, { "ok": "The name length and the extension are both in. Thanks.", "todo": "Stretch: the name length and extension aren't done yet. It's optional." }, { "ok": "The has-@ check gives the form a simple True or False, and your note about -1 is right.", "todo": "Stretch: the has-@ check isn't done yet. Also optional." } ], "approve": "The splitter handles the test addresses correctly.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "That has-@ check is going straight into the sign-up form.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a133 = { "match": "DoorDash Tip Calculator", "core": 4, "brand": { "name": "DOORDASH", "color": "#EB1700", "head": "#EB1700", "ink": "#ffffff", "team": "Checkout", "font": "900 20px Arial,Helvetica,sans-serif", "spacing": "3px" }, "boss": { "name": "Sasha Ivanov", "title": "Checkout Engineer", "initials": "SI" }, "ticket": "CHK-6612", "file": "tip_calc.py", "email": { "subject": "Tip calculator for checkout (and the Dasher pay line)", "paras": [ "Hi, and welcome to the Checkout team!", "At checkout the customer types their food subtotal, a tip, and the delivery distance, and the Dasher's pay is worked out from the result. Whatever people type arrives as text, so numbers have to be converted before any math. Be careful with the phone number though: converting that one would be a mistake.", "`checkout_example.txt` has a worked example to check your answers against, and `pay_rules.md` has the delivery fee and the Dasher pay rules.", "Work through the steps below in order. When you have a version that runs, click **Send to Sasha** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Sasha" }, "files": [ { "name": "checkout_example.txt", "text": "WORKED EXAMPLE\n\n  subtotal       20\n  tip as a decimal   0.15\n  miles          4\n  phone          7705551234\n\n  tip            3.0\n  total          23.0\n  customer pays  26.5\n  Dasher pay     6.9\n\nSTRETCH TASKS\n  Peak Pay: an extra 2.50 for the Dasher\n  a team order of 4" }, { "name": "pay_rules.md", "text": "PAY RULES\n\n  delivery fee     3.50\n  Dasher pay =     1.50 base\n                 + 0.60 for every mile\n                 + the tip\n\nPHONE NUMBERS\n  the Dasher only reads the number, so it is never used in math" } ], "review": { "open": "Thanks, I checked your calculator against the worked example.", "stages": [ { "ok": "All four answers come in the right way: decimals for the numbers and the phone left as text.", "todo": "The four questions aren't right yet. The subtotal, tip rate and miles are decimals, and the phone is not converted." }, { "ok": "The tip, total and what the customer pays match the worked example.", "todo": "The tip, total or customer total doesn't match the example yet." }, { "ok": "The Dasher pay matches the formula: base, miles and tip.", "todo": "The Dasher pay isn't right yet. Check the base, the miles and the tip." }, { "ok": "The phone number stays as text. That keeps a leading zero safe.", "todo": "The phone number isn't printed with its type yet." }, { "ok": "Peak Pay works, and I like the per-mile line.", "todo": "Stretch: Peak Pay isn't done yet. It's optional." }, { "ok": "The team total works, and your note about converting is correct.", "todo": "Stretch: the team order isn't done yet. Also optional." } ], "approve": "All the math matches the worked example.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The Dashers will appreciate the Peak Pay math.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a134 = { "match": "YouTube Creator Studio", "core": 4, "brand": { "name": "YouTube", "color": "#CC0000", "head": "#0F0F0F", "ink": "#ffffff", "team": "Creator Studio", "font": "800 22px Roboto,Arial,sans-serif", "spacing": "-0.5px" }, "boss": { "name": "Terrence Boyd", "title": "Analytics Engineer", "initials": "TB" }, "ticket": "STU-4471", "file": "studio_stats.py", "email": { "subject": "Creator Studio numbers: average, like percent and revenue split", "paras": [ "Hi, thanks for helping on Creator Studio.", "Creators open Studio to see three things first: their average views, the percent of viewers who liked a video and how a revenue pool gets split. Each one is a division, and the answers have to look right: rounded when they should be and never crashing.", "The numbers for one creator are in `creator_stats.txt`, and `studio_notes.md` explains what the screen shows.", "Work through the steps below in order. When you have a version that runs, click **Send to Terrence** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Terrence" }, "files": [ { "name": "creator_stats.txt", "text": "ONE CREATOR\n\n  video 1   1200 views\n  video 2   1500 views\n  video 3    900 views\n\n  likes: 45 from 50 viewers\n  revenue pool: 1000 dollars shared by 3 creators\n  watch time: 1830 minutes over 4 videos\n\nSTRETCH TASKS\n  total views, video 2's share, 5 dislikes\n  a 2000 dollar sponsorship shared by 3 partners" }, { "name": "studio_notes.md", "text": "STUDIO NOTES\n\n  - revenue is shown to the cent (two decimals)\n  - the like percent is shown to one decimal\n  - never divide by zero: a brand new channel with 0 videos would stop the page" } ], "review": { "open": "Thanks, I opened your numbers in Studio.", "stages": [ { "ok": "All nine facts are stored.", "todo": "The creator's numbers aren't all stored yet." }, { "ok": "The average views are right, and your FLOAT note explains the decimal point.", "todo": "The average or the FLOAT comment isn't done yet. Add the three view counts and divide by how many there are." }, { "ok": "The like percent and the revenue share are rounded the way creators see them.", "todo": "The like percent or the revenue share isn't right yet. One decimal for the percent, two for the money." }, { "ok": "Watch time is right, and your CRASH note shows you know what dividing by zero does.", "todo": "The watch time and the CRASH comment aren't done yet." }, { "ok": "Total views, video share and dislike percent all look right.", "todo": "Stretch: total views, share and dislikes aren't done yet. It's optional." }, { "ok": "The sponsorship split shows both the exact and the rounded share.", "todo": "Stretch: the sponsorship split isn't done yet. Also optional." } ], "approve": "Every number Studio shows is right.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The extra stats are exactly what creators ask for. Thanks.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a135 = { "match": "UPS Loading Dock", "core": 4, "brand": { "name": "UPS", "color": "#6B3F1D", "head": "#351C15", "ink": "#FFB500", "team": "Hub Operations", "font": "900 26px Arial,Helvetica,sans-serif", "spacing": "1px" }, "boss": { "name": "Rosa Delgado", "title": "Operations Software Engineer", "initials": "RD" }, "ticket": "HUB-1893", "file": "dock_tools.py", "email": { "subject": "Loading dock numbers (full cartons only)", "paras": [ "Hi, welcome to Hub Operations!", "On the loading dock only **full** cartons ship right away, and the drivers' routes are timed in seconds that our screens show as whole minutes. Both jobs need division that throws away the leftover part. I need the dock tools in code so the screens can use them.", "Today's numbers are in `dock_report.txt`, and `dock_rules.md` has the carton rules.", "Work through the steps below in order. When you have a version that runs, click **Send to Rosa** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Rosa" }, "files": [ { "name": "dock_report.txt", "text": "DOCK REPORT\n\n  packages arrived        100\n  packages per carton      12\n  trucks                   17\n  loading docks             5\n  route time           4000 seconds\n  tracking number         472\n  scale reading            -7\n\nSTRETCH TASKS\n  4 cartons fit on a pallet\n  3600 seconds in an hour\n  partly full cartons must ship too (round up)" }, { "name": "dock_rules.md", "text": "DOCK RULES\n\n  - show the exact carton count and the full carton count\n  - count only full cartons, and whole trucks per dock\n  - times on the screen are whole minutes\n  - a tracking number can be taken apart by its digits\n  - negative scale readings are normal after taring" } ], "review": { "open": "Thanks, I ran your dock tools on today's report.", "stages": [ { "ok": "All seven dock numbers are stored.", "todo": "The dock numbers aren't all stored yet." }, { "ok": "You printed both the exact and the full carton counts, which is what operations wanted.", "todo": "The carton numbers aren't right yet: the exact count with / and the full count with //." }, { "ok": "Trucks per dock is 3 and the route is 66 whole minutes.", "todo": "The trucks per dock or the route minutes aren't right yet." }, { "ok": "The tracking digits are right, and your NEGATIVE note explains why the scale answer is -4.", "todo": "The tracking number pieces, the scale or the NEGATIVE comment aren't done yet." }, { "ok": "Pallets and whole hours are both correct.", "todo": "Stretch: the pallets and hours aren't done yet. It's optional." }, { "ok": "The round-up trick gives 9 cartons and the leftover count is right. Partial cartons ship too, which the dock needs.", "todo": "Stretch: the round-up part isn't done yet. Also optional." } ], "approve": "The dock numbers are all correct.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The round-up formula is going on the dock screens.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a136 = { "match": "Delta Flight Board", "core": 4, "brand": { "name": "DELTA", "color": "#C01933", "head": "#003366", "ink": "#ffffff", "team": "Flight Operations Software", "font": "800 22px Arial,Helvetica,sans-serif", "spacing": "4px" }, "boss": { "name": "Tyrone Jackson", "title": "Operations Software Engineer", "initials": "TJ" }, "ticket": "OPS-2748", "file": "flight_board.py", "email": { "subject": "Flight board math (ATL hub)", "paras": [ "Hi, welcome to Flight Operations!", "The gate boards in Atlanta turn raw numbers into things people can read: a flight time in hours and minutes, which side of the plane a seat is on, how many boarding groups fit, and an arrival hour that wraps around the clock. All of it is about how many whole groups fit and what is left over.", "`board_data.txt` has today's numbers, and `board_rules.md` says what each screen shows.", "Work through the steps below in order. When you have a version that runs, click **Send to Tyrone** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Tyrone" }, "files": [ { "name": "board_data.txt", "text": "TODAY'S BOARD\n\n  ATL to BOS         135 minutes\n  seat row           (typed in by the agent)\n  passengers         200\n  boarding group     6 passengers\n  confirmation       4721\n  departure hour     22\n  flight time        5 hours\n\nSTRETCH TASKS\n  a 95 minute layover\n  gate number 8 (gates go from 0 to 9)" }, { "name": "board_rules.md", "text": "BOARD RULES\n\n  Flight time:    whole hours and the minutes left over\n  Even row:      window seat on the left, odd on the right\n  Boarding:      full groups, and the passengers left over\n  Confirmation:  show the last digit on its own\n  Arrival:       24-hour clock, back to 0 after 23" } ], "review": { "open": "Thanks, I checked your board against today's flights.", "stages": [ { "ok": "The question and every fact are in place.", "todo": "The setup isn't done yet: ask for the seat row and store the six facts." }, { "ok": "The flight time reads 2 hours 15 minutes, and the even-row check uses the remainder and decides True or False by itself.", "todo": "The flight time or the even-row check isn't right yet." }, { "ok": "Boarding groups: 33 full groups and 2 left over, and the confirmation pieces are right.", "todo": "The boarding numbers or the confirmation pieces aren't right yet." }, { "ok": "The arrival hour wraps around the clock correctly to hour 3.", "todo": "The arrival hour isn't wrapping around yet." }, { "ok": "The layover reads right, and the last-group check is useful for gate agents.", "todo": "Stretch: the layover and last group aren't done yet. It's optional." }, { "ok": "Gate rotation and the divisible check both work, and your WRAP note is right.", "todo": "Stretch: the gate and divisibility part isn't done yet. Also optional." } ], "approve": "The board shows the right numbers.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "Gate agents will love the layover line. Thanks for the extras.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a137 = { "match": "Tesla Dashboard Formulas", "core": 4, "brand": { "name": "TESLA", "color": "#E82127", "head": "#171A20", "ink": "#ffffff", "team": "Vehicle Software", "font": "700 22px Arial,Helvetica,sans-serif", "spacing": "8px" }, "boss": { "name": "Kenji Watanabe", "title": "Vehicle Software Engineer", "initials": "KW" }, "ticket": "VEH-8802", "file": "dash_formulas.py", "email": { "subject": "Dashboard formulas (order of operations review)", "paras": [ "Hi, thanks for helping on Vehicle Software.", "The screen in the car runs small formulas for cabin temperature, trip efficiency, drag and charging cost. Python follows the order of operations exactly like math class, so one missing pair of parentheses means a wrong number on the dash. Each formula has to become code exactly.", "The sensor readings are in `sensor_log.txt`, and the formulas are in `formulas.md`.", "Work through the steps below in order. When you have a version that runs, click **Send to Kenji** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Kenji" }, "files": [ { "name": "sensor_log.txt", "text": "SENSOR LOG\n\n  cabin temperature   68 F\n  trip efficiency     250, 280 and 310 watt-hours per mile\n  speed               5\n  charging stop       30 kilowatt-hours\n  cells               20 (they ship in packs of 3)\n\nSTRETCH TASKS\n  20 C back to F, and a 75 kWh battery\n  the average bug QA reported" }, { "name": "formulas.md", "text": "FORMULAS\n\n  Celsius        = (Fahrenheit - 32) x 5 / 9\n  Average        = the three trips added, divided by 3\n  Drag           = speed squared x 2, plus 10\n  Battery cells  = (4 + 2) squared\n  Charging cost  = 4 dollar fee + 0.25 per kWh - 5 dollar coupon\n  Cells to ship  = full packs of 3 only" } ], "review": { "open": "Thanks, I ran your formulas against the sensor log.", "stages": [ { "ok": "All seven sensor readings are stored.", "todo": "The sensor readings aren't all stored yet." }, { "ok": "The cabin temperature is 20.0 Celsius and the average efficiency is 280.0.", "todo": "The Celsius formula or the average isn't right yet. Subtract before you multiply, and add before you divide." }, { "ok": "Drag and battery cells use powers correctly.", "todo": "The powers aren't right yet: drag and battery cells." }, { "ok": "The charging cost is 6.5 and cells that ship is 18, and your ORDER note lists the right order of operations.", "todo": "The charging cost, the cells that ship or the ORDER comment isn't right yet." }, { "ok": "Both conversions match, and the range number is right.", "todo": "Stretch: the Fahrenheit and range part isn't done yet. It's optional." }, { "ok": "You reproduced the average bug, and your PARENS note explains exactly why it happens.", "todo": "Stretch: the average bug isn't done yet. Also optional." } ], "approve": "Every formula on the dash is correct.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The range line goes into the next software release.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a138 = { "match": "Roblox Robux Tracker", "core": 3, "brand": { "name": "ROBLOX", "color": "#00A2FF", "head": "#232527", "ink": "#ffffff", "team": "Economy", "font": "900 22px Arial,Helvetica,sans-serif", "spacing": "3px" }, "boss": { "name": "Imani Clarke", "title": "Economy Engineer", "initials": "IC" }, "ticket": "ECO-1301", "file": "robux_tracker.py", "email": { "subject": "Robux balance tracing (for the economy audit)", "paras": [ "Hi, welcome to the Economy team!", "Our audit team asks engineers to trace a player's Robux balance by hand before running any code: what does every variable hold after each line? The tracker has to change one balance line by line, and a trade between two players has to move Robux from one account to the other.", "`audit_events.txt` lists the events in order, and `trace_notes.md` explains how the audit wants the trace written.", "Work through the steps below in order. When you have a version that runs, click **Send to Imani** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Imani" }, "files": [ { "name": "audit_events.txt", "text": "AUDIT EVENTS (in order)\n\n  start balance              100\n  the player sells an item   +50\n  the player buys a hat      -30\n  a sale event               doubles the balance\n\nTRADE\n  me 80, friend 20\n  I give my friend 30\n\nTRAP\n  price 10, cost is price times 2, then the price becomes 15\n\nSTRETCH TASKS\n  a marketplace fee of 60\n  a second trade of 25" }, { "name": "trace_notes.md", "text": "TRACE NOTES\n\n  - one comment per change line, starting with TRACE:\n  - write the number the balance holds AFTER that line\n  - a variable does not follow another variable: it keeps the value it had when it was set" } ], "review": { "open": "Thanks, I traced your tracker by hand and then ran it.", "stages": [ { "ok": "The balance changes run in order on one variable, and your three TRACE comments (150, 120 and 240) are all right. The audit team will be happy.", "todo": "The balance changes or the three TRACE comments aren't right yet: change the same variable each time and write the number after each change." }, { "ok": "The trade moves Robux from one player to the other correctly.", "todo": "The trade isn't right yet. Both balances change." }, { "ok": "Your note explains why cost didn't change when price did. That's the most common mistake in the audit.", "todo": "The price and cost example isn't done yet." }, { "ok": "The marketplace fee comes out of the same balance and the trace is right.", "todo": "Stretch: the marketplace fee isn't done yet. It's optional." }, { "ok": "The second trade is traced correctly with both new balances.", "todo": "Stretch: the second trade isn't done yet. Also optional." } ], "approve": "The tracker and the trades check out.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "We'll use your trace as the example for next quarter's audit.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a139 = { "match": "Instagram Account Flags", "core": 4, "brand": { "name": "Instagram", "color": "#C13584", "head": "#ffffff", "ink": "#C13584", "team": "Accounts Platform", "font": "italic 700 26px Georgia,serif", "spacing": "0" }, "boss": { "name": "Maya Torres", "title": "Accounts Platform Engineer", "initials": "MT" }, "ticket": "ACC-5530", "file": "account_flags.py", "email": { "subject": "Account flags: which features switch on for an account?", "paras": [ "Hi, and welcome to Accounts Platform!", "Every account has a handful of yes or no facts, and many features switch on or off by comparing a number, such as the follower count, with a limit. I need a small script that stores an account's facts and shows which switches are on, using real True and False answers and nothing typed in by hand.", "The account to test is in `test_account.txt`, and `feature_limits.md` has the limit for each switch.", "Work through the steps below in order. When you have a version that runs, click **Send to Maya** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Maya" }, "files": [ { "name": "test_account.txt", "text": "TEST ACCOUNT\n\n  is_verified        True\n  is_private         False\n  followers          12500\n  likes (one post)   250\n\nSTRETCH TASKS\n  a goal of 15000 followers\n  does the post miss 250 likes? what type is a True or False?" }, { "name": "feature_limits.md", "text": "FEATURE LIMITS\n\n  Over 10000 followers    the account gets the growth chart\n  Under 1000 followers    the account is flagged as small\n  Can go live             1000 followers or more\n  Mega                    more than 1000000 followers\n  Public account          the opposite of private\n  Not verified            the opposite of verified\n\nNOTE\n  every answer comes from a comparison, never typed in" } ], "review": { "open": "Thanks, I ran your script on the test account.", "stages": [ { "ok": "The account facts are stored with the right values.", "todo": "The account facts aren't all stored yet." }, { "ok": "All four follower checks come from real comparisons.", "todo": "The follower checks aren't right yet. Let Python answer True or False." }, { "ok": "not flips the right values.", "todo": "The not checks aren't right yet." }, { "ok": "You kept = and == apart, and your note explains the difference well.", "todo": "The likes check and the EQUALS comment aren't done yet." }, { "ok": "The goal check and its opposite both work.", "todo": "Stretch: the goal isn't done yet. It's optional." }, { "ok": "The != check and the type check work, and your BOOL note is correct.", "todo": "Stretch: the != and type part isn't done yet. Also optional." } ], "approve": "Every switch for the test account is right.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The goal feature is going into the next creator tools update.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a140 = { "match": "Disney+ Access Rules", "core": 4, "brand": { "name": "Disney+", "color": "#113CCF", "head": "#040714", "ink": "#ffffff", "team": "Streaming Access", "font": "700 26px Georgia,serif", "spacing": "0" }, "boss": { "name": "Grace Okafor", "title": "Streaming Access Engineer", "initials": "GO" }, "ticket": "ACS-2204", "file": "access_rules.py", "email": { "subject": "Who can stream? (access rules for the new profile screen)", "paras": [ "Hi, thanks for helping on Streaming Access!", "Whether a viewer can stream, gets a discount or lands on a teen profile is decided by combining yes or no facts with **and**, **or** and **not**. The park team wants the same logic for a ride gate, so the rules have to be exact.", "The viewer to test with is in `test_viewer.txt`, and `access_rules.md` lists every rule in plain English.", "Work through the steps below in order. When you have a version that runs, click **Send to Grace** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Grace" }, "files": [ { "name": "test_viewer.txt", "text": "TEST VIEWER\n\n  has_subscription   True\n  payment_failed     False\n  age                15\n  is_student         True\n  is_military        False\n  has_ticket         True\n\nRIDE GATE\n  the height in inches is typed in by the cast member\n\nSTRETCH TASKS\n  a perk rule written two ways\n  downloads and ads" }, { "name": "access_rules.md", "text": "ACCESS RULES\n\n  Can stream     a subscription AND the payment has not failed\n  Discount       a student OR a military member\n  Teen profile   13 or older AND 17 or younger\n  Can ride       at least 40 inches tall AND a ticket\n  Needs adult    under 48 inches OR under 10 years old\n\nNOTE\n  with no parentheses, Python does AND before OR" } ], "review": { "open": "Thanks, I ran your rules on the test viewer.", "stages": [ { "ok": "The viewer facts are stored and the ride gate asks for the height.", "todo": "The setup isn't done yet: the six facts and the height question." }, { "ok": "can_stream uses and with not and gives the right answer.", "todo": "The streaming rule isn't right yet: a subscription and no failed payment." }, { "ok": "The discount uses or and the teen profile checks both ends.", "todo": "The discount or the teen profile isn't right yet." }, { "ok": "The ride gate works for a 44 inch rider.", "todo": "The ride gate isn't right yet: the height check and the adult rule." }, { "ok": "Perk A and Perk B show how parentheses change the answer, and your FIRST note is right.", "todo": "Stretch: the perk rules and the FIRST comment aren't done yet. It's optional." }, { "ok": "Downloads and ads are both right.", "todo": "Stretch: downloads and ads aren't done yet. Also optional." } ], "approve": "Every access rule gives the right answer.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "I'm putting your perk rule demo into the access spec.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a141 = { "match": "Wordle Guess Checker", "core": 4, "brand": { "name": "The New York Times", "color": "#4F8A4B", "head": "#ffffff", "ink": "#121212", "team": "Games Engineering", "font": "700 italic 24px Georgia,'Times New Roman',serif", "spacing": "-0.5px" }, "boss": { "name": "Theo Grant", "title": "Games Engineer", "initials": "TG" }, "ticket": "GAM-6023", "file": "guess_checker.py", "email": { "subject": "Guess checker (tries and streaks too)", "paras": [ "Hi, welcome to Games Engineering!", "Every guess in a word game is checked against the secret word, and the tries and the streak pages run on the same six comparison operators. The checker has to be exact at the boundaries: five letters means exactly five, and a seven day streak has to earn its badge.", "`today_puzzle.txt` has the test values, and `checker_spec.md` lists every check.", "Work through the steps below in order. When you have a version that runs, click **Send to Theo** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Theo" }, "files": [ { "name": "today_puzzle.txt", "text": "TODAY'S PUZZLE (for testing only)\n\n  secret word      crane\n  the player's guess is typed in\n  attempts used    4 of 6\n  streak           7 days\n\nSTRETCH TASKS\n  hard mode: last attempt, attempts left, same first letter\n  streak milestones" }, { "name": "checker_spec.md", "text": "CHECKER SPEC\n\n  Correct:         does the guess equal the secret?\n  Wrong length:    a guess has exactly 5 letters, so is the length not 5?\n  Under, At, Over and Within limit   compare attempts with the maximum\n  Badge:           a streak of 7 days or more earns it\n  Odd streak, Double beats 10\n  Matches CRANE:   answers are lowercase, so a capital guess is different" } ], "review": { "open": "Thanks, I tried your checker with a few guesses.", "stages": [ { "ok": "The secret, the guess and the first two checks are right.", "todo": "The first checks aren't right yet: equal to the secret, and the length not equal to 5." }, { "ok": "All four tries comparisons are correct.", "todo": "The tries comparisons aren't all right yet." }, { "ok": "The badge handles the boundary correctly, and the odd and doubled streak checks are right.", "todo": "The badge or the streak questions aren't right yet. The boundary number itself has to count." }, { "ok": "You showed what a capital-letter comparison does.", "todo": "The capital-letter comparison isn't done yet." }, { "ok": "The hard-mode checks work.", "todo": "Stretch: the hard-mode checks aren't done yet. It's optional." }, { "ok": "The streak milestones and your BOUNDARY note are right.", "todo": "Stretch: the streak milestones aren't done yet. Also optional." } ], "approve": "The checker is exact at every boundary.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The hard-mode checks are exactly what the puzzle team asked about.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a142 = { "match": "Peloton Workout Alerts", "core": 4, "brand": { "name": "PELOTON", "color": "#DF1C2F", "head": "#181A1D", "ink": "#ffffff", "team": "Bike Software", "font": "800 22px Arial,Helvetica,sans-serif", "spacing": "4px" }, "boss": { "name": "Dani Reyes", "title": "Bike Software Engineer", "initials": "DR" }, "ticket": "BIK-3917", "file": "workout_alerts.py", "email": { "subject": "Heart rate alerts for the bike screen", "paras": [ "Hi, welcome to Bike Software!", "During a class the bike screen watches the rider's numbers and pops up messages. An alert should appear only when its condition is true, the save line must show up no matter what, and a few alerts depend on two things at once. Be careful with indentation: it decides what belongs to an alert.", "`alert_rules.txt` lists every alert and its limit, and `test_rides.md` has the rides to try.", "Work through the steps below in order. When you have a version that runs, click **Send to Dani** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Dani" }, "files": [ { "name": "alert_rules.txt", "text": "ALERT RULES\n\n  heart rate over 170         Slow down, then Drink water\n  monitor AND at least 150    Red zone\n  cadence over 80             Fast pedaling\n  cadence over 60             Good pedaling\n  heart rate over 100 AND cadence over 80    Peak interval\n  at least 160                +10 points (riders start at 40)\n  Workout saved               always shows, last\n\nSTRETCH TASKS\n  resistance 45 and bonus points\n  a coach message for very high heart rates" }, { "name": "test_rides.md", "text": "TEST RIDES\n\n  ride A: heart rate 180, cadence 85, monitor connected\n  ride B: heart rate 120\n\nThe bike asks: Heart rate?" } ], "review": { "open": "Thanks, I rode your alerts on both test rides.", "stages": [ { "ok": "The ride data is in place, with the question for the heart rate.", "todo": "The ride data isn't done yet: ask for the heart rate and store the other three facts." }, { "ok": "Slow down and Drink water only show when the alert fires, and Red zone needs both conditions. The indentation is right.", "todo": "The heart rate alerts aren't right yet. Both lines belong to the if, and Red zone needs the monitor and the heart rate." }, { "ok": "Two separate ifs and the nested one all work: a cadence of 85 prints both messages and the Peak interval.", "todo": "The cadence ifs aren't right yet: two separate ifs and an if inside an if." }, { "ok": "The points change inside the if, and Workout saved always shows at the end.", "todo": "The points or the Workout saved line isn't right yet." }, { "ok": "The resistance alert and the bonus points are correct, and they run before the ride is saved.", "todo": "Stretch: resistance and bonus points aren't done yet. It's optional." }, { "ok": "The coach message is nested correctly, and your INDENT note is right.", "todo": "Stretch: the coach message isn't done yet. Also optional." } ], "approve": "Every alert fires exactly when it should.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The coach message is going to the class instructors for feedback.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a143 = { "match": "Starbucks Rewards Tiers", "core": 4, "brand": { "name": "Starbucks", "color": "#00704A", "head": "#00704A", "ink": "#ffffff", "team": "Rewards", "font": "800 22px Georgia,serif", "spacing": "0" }, "boss": { "name": "Jamal Carter", "title": "Rewards Engineer", "initials": "JC" }, "ticket": "RWD-4408", "file": "rewards_tiers.py", "email": { "subject": "Rewards tiers and promos (before the holiday launch)", "paras": [ "Hi, welcome to Rewards!", "The app turns a member's star count into a tier, a bonus and a couple of promos. For the tiers the program has to pick **exactly one** choice from a chain, but two of our promos can both apply to the same member at once, so you'll need to use the right tool for each.", "The tier limits are in `tiers.txt`, and `promos.md` explains the promos.", "Work through the steps below in order. When you have a version that runs, click **Send to Jamal** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Jamal" }, "files": [ { "name": "tiers.txt", "text": "TIERS (by stars)\n\n  300 or more    Gold\n  100 or more    Green\n  25 or more     Welcome\n  below 25       New\n\nFREE DRINK\n  50 stars or more\n\nBONUS STARS (by purchases)\n  10 or more    20 stars\n  5 or more     10 stars\n  1 or more      5 stars\n  none           0\n\nSTRETCH TASKS\n  the price of a drink by cup size\n  an even-stars promo" }, { "name": "promos.md", "text": "PROMOS\n\n  Promo A       over 50 stars\n  Promo B       over 20 stars\n  Even stars    a promo that runs only on even star counts\n\nA member with 60 stars qualifies for A and B at the same time." } ], "review": { "open": "Thanks, I tried your rewards program with a few members.", "stages": [ { "ok": "The two questions and the free drink check both have both branches.", "todo": "The first step isn't right yet: ask for the stars and purchases, then an if and an else for the free drink." }, { "ok": "The tier chain picks exactly one tier, in an order that works.", "todo": "The tier chain isn't right yet. Check the order of the limits." }, { "ok": "Bonus stars come from one chain, and your ORDER note explains why the biggest limit goes first.", "todo": "The bonus chain or the ORDER comment isn't done yet." }, { "ok": "Both promos print for 60 stars because they're separate ifs.", "todo": "The two promos aren't right yet. They must be separate ifs so both can happen." }, { "ok": "The price by cup size works.", "todo": "Stretch: the price by cup size isn't done yet. It's optional." }, { "ok": "The even-stars promo works with the remainder.", "todo": "Stretch: the even-stars promo isn't done yet. Also optional." } ], "approve": "The tiers and promos work for every member.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The cup size pricing is going into the holiday launch.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a144 = { "match": "Fortnite Controller Events", "core": 4, "brand": { "name": "FORTNITE", "color": "#7A3CF2", "head": "#1B1340", "ink": "#ffffff", "team": "Input Team", "font": "900 italic 22px Arial,Helvetica,sans-serif", "spacing": "2px" }, "boss": { "name": "Kai Nakamura", "title": "Input Systems Engineer", "initials": "KN" }, "ticket": "INP-1187", "file": "controller.py", "email": { "subject": "Controller events and handlers (prototype for the new build mode)", "paras": [ "Hi, welcome to the Input team!", "The game never knows ahead of time what a player will press. Each key press arrives as an **event** that carries the name of the key, and one **handler** decides what to do. There's no game window in this editor, so you'll make the key presses yourself and hand them to your handler. Key names have to match exactly.", "`key_map.txt` lists what each key does, and `test_inputs.md` has the sequences we test with.", "Work through the steps below in order. When you have a version that runs, click **Send to Kai** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Kai" }, "files": [ { "name": "key_map.txt", "text": "KEY MAP\n\n  d     move right: x + 15\n  a     move left: x - 15\n  h     hit: health - 25\n  m     medkit: health + 50\n  q     Build mode\n  anything else    Unknown key\n\nSTART\n  x 100, health 100\n\nSTRETCH TASKS\n  emotes on the keys 1 and 2\n  build mode that ignores caps lock" }, { "name": "test_inputs.md", "text": "TEST INPUTS\n\n  session: d, d, a, h, h, h, m, z\n  names: q, then a capital Q\n\nNOTE\n  capital letters are different keys" } ], "review": { "open": "Thanks, I fed your handler a few key presses.", "stages": [ { "ok": "The Event class stores the key, and the player starts at the right numbers.", "todo": "The Event class isn't right yet: it needs a constructor that stores the key, plus x and health." }, { "ok": "The control handler uses one chain and handles the unknown key.", "todo": "The control handler isn't right yet: one if, elif, else chain on the key, with global x and global health." }, { "ok": "The session ends at x 115 and health 75, and the unknown key is reported.", "todo": "The session isn't right yet: eight key presses, then print x and health." }, { "ok": "Build mode only appears for q, and your MATCH note explains why Q did nothing.", "todo": "The key name check or the MATCH comment isn't done yet." }, { "ok": "The emotes work.", "todo": "Stretch: the emotes aren't done yet. It's optional." }, { "ok": "Build mode now works with caps lock on.", "todo": "Stretch: the caps lock fix isn't done yet. Also optional." } ], "approve": "The handler reacts to every key correctly.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The caps lock fix is going into the prototype.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a145 = { "match": "SpaceX Launch Countdown", "core": 4, "brand": { "name": "SPACEX", "color": "#005288", "head": "#000000", "ink": "#ffffff", "team": "Flight Software", "font": "700 22px Arial,Helvetica,sans-serif", "spacing": "6px" }, "boss": { "name": "Rohan Patel", "title": "Flight Software Engineer", "initials": "RP" }, "ticket": "FSW-0912", "file": "countdown.py", "email": { "subject": "Launch countdown loops (checklist for the static fire)", "paras": [ "Hi, welcome to Flight Software!", "A launch is full of repeating jobs: a row of system checks, a set of valves, a countdown. A **for loop** repeats work a set number of times, and `range()` says how many. The stop number is never included, so watch that one closely, and the countdown has to come last.", "`checklist.txt` has what has to run in order, and `ranges.md` has the valve and stage numbering.", "Work through the steps below in order. When you have a version that runs, click **Send to Rohan** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Rohan" }, "files": [ { "name": "checklist.txt", "text": "STATIC FIRE CHECKLIST (in order)\n\n  Engine ready      3 times\n  system checks     1 through 5\n  fuel valves       0, 2, 4, 6, 8, 10\n  stage numbers     1 through 8 (add them up)\n  numbers 1 to 12   count the even ones\n  countdown         10 down to 1, then Liftoff!\n\nSTRETCH TASKS\n  odd stage numbers from 1 to 9\n  fuel loading: the sum of the squares of 1 to 5" }, { "name": "ranges.md", "text": "RANGES\n\n  - the stop number is not included\n  - a step is the number added each time\n  - a negative step counts down" } ], "review": { "open": "Thanks, I ran your checklist loops.", "stages": [ { "ok": "Engine ready repeats three times and the numbered checks run 1 through 5.", "todo": "The first loops aren't right yet: Engine ready three times, then checks 1 through 5 (the stop number isn't included)." }, { "ok": "The valves use one loop with a step.", "todo": "The valves aren't right yet: 0 to 10 in steps of 2." }, { "ok": "The total is 36 and the even count is 6, using an accumulator and an if inside a loop.", "todo": "The totals and counts aren't right yet." }, { "ok": "The countdown ends with one Liftoff after the loop.", "todo": "The countdown isn't right yet: 10 down to 1, then Liftoff once after the loop." }, { "ok": "The odd stages loop works, it runs before the countdown, and your STEP note is right.", "todo": "Stretch: the odd stages aren't done yet. It's optional." }, { "ok": "The fuel loading squares are right.", "todo": "Stretch: the fuel loading isn't done yet. Also optional." } ], "approve": "Every loop in the checklist works.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The fuel loading loop is going into the telemetry test.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a146 = { "match": "Amazon Cart Checker", "core": 3, "brand": { "name": "amazon", "color": "#C45500", "head": "#232F3E", "ink": "#ffffff", "team": "Checkout", "font": "800 26px Arial,Helvetica,sans-serif", "spacing": "-0.5px" }, "boss": { "name": "Nina Alvarez", "title": "Checkout Engineer", "initials": "NA" }, "ticket": "CHK-7745", "file": "cart_checker.py", "email": { "subject": "Cart checker: visit every item", "paras": [ "Hi, welcome to Checkout!", "A shopping cart is a list of things, and the code behind it has to visit every item. A **for loop** can walk through a list or through the letters of a text, and the loop variable holds the **value** itself, not a position. I need the items shown, shipping added, totals and an average, and a few filters.", "The test cart is in `test_cart.txt`, and `cart_rules.md` has shipping and the free shipping limit.", "Work through the steps below in order. When you have a version that runs, click **Send to Nina** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Nina" }, "files": [ { "name": "test_cart.txt", "text": "TEST CART\n\n  items          book, lamp, mug\n  prices         4, 6, 8, 10\n  tracking       1Z999AA1\n\nSTRETCH TASKS\n  long item names\n  the cheapest price and sale prices" }, { "name": "cart_rules.md", "text": "CART RULES\n\n  shipping        2 dollars added to every price\n  free shipping   starts at 5 dollars per item (count the items over 5)\n  tracking        count how many 9s are in the code\n  the average     the total divided by how many prices there are" } ], "review": { "open": "Thanks, I ran your checker on the test cart.", "stages": [ { "ok": "The cart is set up and every item is shown from the list.", "todo": "The cart isn't set up yet: the three variables and a loop over the items." }, { "ok": "Shipping, the total and the average are right, and the average uses the length of the list.", "todo": "The shipping prices, the total or the average isn't right yet." }, { "ok": "The filters count 3 items over 5 and three 9s in the tracking code.", "todo": "The filters aren't right yet: an if inside a loop, for the prices and for the tracking letters." }, { "ok": "The long names count is right.", "todo": "Stretch: the long names aren't done yet. It's optional." }, { "ok": "The cheapest price and the sale prices are right.", "todo": "Stretch: the cheapest price and sale prices aren't done yet. Also optional." } ], "approve": "The cart numbers all match.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The cheapest-item finder is going into the cart summary.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a147 = { "match": "Twitch Stream Stats", "core": 3, "brand": { "name": "twitch", "color": "#772CE8", "head": "#9146FF", "ink": "#ffffff", "team": "Analytics", "font": "800 26px Arial,Helvetica,sans-serif", "spacing": "-1px" }, "boss": { "name": "Leo Park", "title": "Analytics Engineer", "initials": "LP" }, "ticket": "ANL-2236", "file": "stream_stats.py", "email": { "subject": "Stream stats for the streamer dashboard", "paras": [ "Hi, welcome to Analytics!", "Streamers want totals, averages, peaks and counts from the viewer numbers of their last five streams. Each one is a loop with a variable that **builds up** a result, so the variable has to start in the right place before the loop begins.", "`last_five_streams.txt` has the numbers, and `dashboard_spec.md` lists each stat.", "Work through the steps below in order. When you have a version that runs, click **Send to Leo** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Leo" }, "files": [ { "name": "last_five_streams.txt", "text": "LAST FIVE STREAMS\n\n  viewers: 120, 340, 95, 410, 210\n  chat message: Poggers\n\nSTRETCH TASKS\n  the lowest stream and the range\n  how many streams beat the average" }, { "name": "dashboard_spec.md", "text": "DASHBOARD SPEC\n\n  Total viewers\n  Average viewers    the total divided by the number of streams\n  Peak viewers       the biggest number\n  Big streams        more than 200 viewers\n  Letter g           how many g's are in the chat message" } ], "review": { "open": "Thanks, I ran your stats on the last five streams.", "stages": [ { "ok": "The total and the average are right, and the average uses the length of the list.", "todo": "The total or the average isn't right yet. Start the total at 0 and add every number." }, { "ok": "The peak finder only replaces the peak when a bigger number shows up.", "todo": "The peak isn't right yet." }, { "ok": "Big streams and the letter counter both work.", "todo": "The big streams count or the letter count isn't right yet." }, { "ok": "The lowest stream and the range are right.", "todo": "Stretch: the lowest and the range aren't done yet. It's optional." }, { "ok": "Above average is right, and your ACCUM note explains why a counter starts at zero.", "todo": "Stretch: the above-average count isn't done yet. Also optional." } ], "approve": "Every stat on the dashboard matches.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "Streamers have been asking for the above-average stat.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a148 = { "match": "PlayStation 5 Restock", "core": 3, "brand": { "name": "PlayStation", "color": "#0070D1", "head": "#003087", "ink": "#ffffff", "team": "PlayStation Direct", "font": "800 italic 22px Arial,Helvetica,sans-serif", "spacing": "0" }, "boss": { "name": "Sam Whitfield", "title": "Direct Commerce Engineer", "initials": "SW" }, "ticket": "PSD-5190", "file": "restock.py", "email": { "subject": "Restock day: loops that don't know how many steps they need", "paras": [ "Hi, welcome to PlayStation Direct!", "When a restock is announced nobody knows how many steps it will take: fans retype a queue code, shipments arrive, stock sells down. A **while loop** keeps going as long as its condition is True, which is what we need when the count isn't known ahead of time. The most important rule is that something inside the loop has to change.", "`restock_day.txt` has the numbers for the day, and `queue_rules.md` has the rules for the waiting room.", "Work through the steps below in order. When you have a version that runs, click **Send to Sam** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Sam" }, "files": [ { "name": "restock_day.txt", "text": "RESTOCK DAY (in order)\n\n  queue code           PS5\n  shipments            1 to 3\n  consoles in stock    3\n  a fan saves          75 dollars a week toward a 500 dollar bundle\n\nSTRETCH TASKS\n  people in line, counting down by 2\n  a reseller who doubles the price every day" }, { "name": "queue_rules.md", "text": "QUEUE RULES\n\n  - the fan types PS5 to get in\n  - a wrong code means ask again with the same question\n  - a loop whose variable never changes never stops" } ], "review": { "open": "Thanks, I ran your restock loops.", "stages": [ { "ok": "The queue code keeps asking until it is right.", "todo": "The waiting room isn't right yet: ask once, then while the code is wrong ask again." }, { "ok": "Shipments count up to 3, and stock counts down to 0 and prints Sold out after the loop.", "todo": "The shipments or the stock countdown aren't right yet." }, { "ok": "The savings loop gives 7 weeks and 525 dollars, and your FOREVER note explains what would happen without the update.", "todo": "The savings loop or the FOREVER comment isn't right yet." }, { "ok": "The waiting line counts down correctly.", "todo": "Stretch: the waiting line isn't done yet. It's optional." }, { "ok": "The doubling prices loop works, and your STOP note explains why it ends.", "todo": "Stretch: the doubling prices aren't done yet. Also optional." } ], "approve": "Every restock loop works and stops when it should.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "I'm showing the doubling price simulation to the pricing team.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a149 = { "match": "Venmo Payment Loops", "core": 4, "brand": { "name": "venmo", "color": "#3D95CE", "head": "#3D95CE", "ink": "#ffffff", "team": "Payments Safety", "font": "800 26px 'Trebuchet MS',Arial,sans-serif", "spacing": "-1px" }, "boss": { "name": "Tasha Williams", "title": "Payments Safety Engineer", "initials": "TW" }, "ticket": "PAY-3381", "file": "payment_loops.py", "email": { "subject": "Payment loops: PIN, limits and refunds", "paras": [ "Hi, welcome to Payments Safety!", "Some loops can't know when to stop until they've already asked a question: a PIN that has to be right, an amount that has to be in range, a list that ends when someone types a stopping number. The **loop and a half** uses `while True` with a `break` to stop in the middle. Please make sure every one of these loops can actually end.", "`safety_rules.txt` lists the limits, and `test_sessions.md` shows what the tester types.", "Work through the steps below in order. When you have a version that runs, click **Send to Tasha** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Tasha" }, "files": [ { "name": "safety_rules.txt", "text": "SAFETY RULES (one session, in order)\n\n  PIN                 1234\n  send range          1 to 500 dollars\n  split a bill        payments add up until the tester types 0\n  refunds             add up until the tester types -1 (no break)\n\nSTRETCH TASKS\n  recent payments 20, 15, 600, 40: flag anything over 500\n  a 100 dollar daily limit" }, { "name": "test_sessions.md", "text": "TEST SESSIONS\n\n  PIN: a wrong PIN, then 1234\n  Send amount: 900, then 50\n  Payment: 10, 30, then 0\n  Refund: 5, 7, then -1" } ], "review": { "open": "Thanks, I ran your loops with the test sessions.", "stages": [ { "ok": "The PIN loop asks once in the code and breaks on 1234.", "todo": "The PIN loop isn't right yet: while True, one question, break on the right PIN." }, { "ok": "Only amounts from 1 to 500 are accepted.", "todo": "The valid amount loop isn't right yet. Check both ends with and." }, { "ok": "The sentinel loop adds payments until 0 and totals 40.", "todo": "The payment total isn't right yet." }, { "ok": "The refund loop works without a break.", "todo": "The refund loop isn't right yet: ask once before the loop and again at the bottom." }, { "ok": "The review loop flags 600 and stops.", "todo": "Stretch: the flag loop isn't done yet. It's optional." }, { "ok": "The daily limit stops the loop at the right payment.", "todo": "Stretch: the daily limit isn't done yet. Also optional." } ], "approve": "Every loop can end and every limit is enforced.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The daily limit is going into the safety review.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a150 = { "match": "Mario Kart Item Box", "core": 3, "brand": { "name": "NINTENDO", "color": "#E60012", "head": "#E60012", "ink": "#ffffff", "team": "Kart Gameplay", "font": "900 20px 'Arial Black',Arial,Helvetica,sans-serif", "spacing": "3px" }, "boss": { "name": "Hana Mori", "title": "Gameplay Programmer", "initials": "HM" }, "ticket": "KART-0207", "file": "item_box.py", "email": { "subject": "Item box prototype, please try random numbers", "paras": [ "Hello! Thanks for joining the Kart Gameplay team.", "When a racer drives through an item box, the game rolls random numbers to decide what they get. I need a small prototype that shows the random library doing the jobs we use it for, so the designers can see how it behaves.", "The item list and the rules are in `item_table.txt`. Please build the prototype in the steps below.", "Work through the steps below in order. When you have a version that runs, click **Send to Hana** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Hana" }, "files": [ { "name": "item_table.txt", "text": "ITEM BOX PROTOTYPE\n\nboost roll      a six-sided die (1 to 6)\nturbo           1 to 3 seconds\nstart side      coin flip: 0 is Heads, 1 is Tails\nitems           banana, mushroom, star\nrace length     5 item boxes, total the dice\nre-roll rule    roll until a 6 comes up, count the rolls\n\nSTRETCH TASKS\n  three laps: one random item per lap\n  blue shell: 1 out of 10" }, { "name": "random_notes.md", "text": "NOTES ON RANDOM\n\n  import random first\n  randint(a, b) includes both a and b\n  choice(list) picks one item from a list\n  a loop that must stop on a special roll is a while loop" } ], "review": { "open": "Thanks, I ran through your item box prototype.", "stages": [ { "ok": "The boost roll, the turbo and the coin flip all work, and both ends of each range count.", "todo": "The first part isn't right yet: import random, a six-sided die, a turbo from 1 to 3, and a coin flip with an if and an else." }, { "ok": "Picking an item from the list works, and the five-roll total is correct.", "todo": "The item pick or the five-roll total isn't done yet: a random choice from the list, and a loop that adds a roll each time." }, { "ok": "Rolling until a six works, and the roll counter is correct. That's the trickiest piece and you got it.", "todo": "The roll-until-six part isn't done yet: a while loop that stops on a 6 and counts the rolls." }, { "ok": "The three-lap race is great: one item per lap. I'm going to show the designers.", "todo": "Stretch: the three-lap race isn't done yet. It's optional." }, { "ok": "The blue shell odds are correct, 1 out of 10, with Safe otherwise. Thank you for taking the extra task.", "todo": "Stretch: the blue shell isn't done yet. Also optional." } ], "approve": "That covers everything the prototype needed. Nice work.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "You did the stretch tasks too. The designers will be using your loop in the race demo.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a151 = { "match": "Uber Eats Messages", "core": 3, "brand": { "name": "Uber Eats", "color": "#05944F", "head": "#000000", "ink": "#06C167", "team": "Consumer App", "font": "800 24px Arial,Helvetica,sans-serif", "spacing": "-0.5px" }, "boss": { "name": "Priyanka Desai", "title": "Consumer App Engineer", "initials": "PD" }, "ticket": "APP-8814", "file": "messages.py", "email": { "subject": "Reusable messages for the app (write once, call anywhere)", "paras": [ "Hi, welcome to the Consumer App team!", "The app sends the same kinds of messages over and over: a welcome, a greeting by name, a tip line, a banner. Instead of copying the code every time, we write each message once as a **function** and call it wherever we need it. I'd like the functions together at the top of the file, and the order flow at the bottom.", "`message_list.txt` has the messages and the order they appear in, and `function_notes.md` has our team conventions.", "Work through the steps below in order. When you have a version that runs, click **Send to Priyanka** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Priyanka" }, "files": [ { "name": "message_list.txt", "text": "MESSAGES\n\n  Welcome     Welcome to Uber Eats!\n  Greeting    Hi, <customer name>\n  Tip line    Tip: <20 percent of the bill>\n  Banner      *** <text> ***\n  Delivery    Delivering\n\nTHE ORDER (what the customer sees, in order)\n  welcome, greeting for Maria, banner Order placed, tip on a 30 dollar bill,\n  delivery, banner Delivered\n\nSTRETCH TASKS\n  a delivery fee of 2 dollars per mile (3 miles, then 8 miles)\n  a checkout that calls the delivery message" }, { "name": "function_notes.md", "text": "TEAM CONVENTIONS\n\n  - functions first, the program that calls them last\n  - one function does one job\n  - the name says what it does\n  - a function runs only when it is called\n  - a function can call another function" } ], "review": { "open": "Thanks, I ran your messages.", "stages": [ { "ok": "welcome and greet_customer are defined once at the top, with the parameter in the right place.", "todo": "The first two functions aren't right yet: welcome with no parameter, and greet_customer with one." }, { "ok": "show_tip, banner and deliver all work, and your PARAMETER note is right.", "todo": "The three functions or the PARAMETER comment isn't done yet." }, { "ok": "The order flow runs every message in the order the customer sees them, and the banner works with a variable too.", "todo": "The order flow isn't right yet: call each function in order, then use a variable for the last banner." }, { "ok": "The delivery fee is right for both trips, and it sits with the other functions.", "todo": "Stretch: the delivery fees aren't done yet. It's optional." }, { "ok": "Checkout calls deliver, and your FLOW note describes the jump correctly.", "todo": "Stretch: the checkout function isn't done yet. Also optional." } ], "approve": "Every message is written once and works everywhere.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The delivery fee function is going into the app update.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a152 = { "match": "Zillow Listing Tools", "core": 3, "brand": { "name": "Zillow", "color": "#006AFF", "head": "#006AFF", "ink": "#ffffff", "team": "Listings Tools", "font": "800 26px Arial,Helvetica,sans-serif", "spacing": "-1px" }, "boss": { "name": "Carmen Ortiz", "title": "Listings Tools Engineer", "initials": "CO" }, "ticket": "LST-2640", "file": "listing_tools.py", "email": { "subject": "Listing tools that use more than one number", "paras": [ "Hi, welcome to Listings Tools!", "Every home listing needs numbers worked out from several facts at once, so each tool needs **more than one parameter**, and the values have to go in **in the right order**. A swapped pair of numbers once showed a house at a fraction of a cent per square foot, and nobody wants that again. Please keep the tools together at the top and the listing page at the bottom.", "`sample_listings.txt` has the homes to test with, and `tool_specs.md` lists each tool.", "Work through the steps below in order. When you have a version that runs, click **Send to Carmen** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Carmen" }, "files": [ { "name": "sample_listings.txt", "text": "SAMPLE LISTINGS\n\n  a lot that is 50 by 100\n  a 300000 dollar home with 1500 square feet\n  rent 1200, utilities 150, parking 75\n  88 Main St, 2 bedrooms\n\nSTRETCH TASKS\n  agent commissions (300000 at 3 percent, 500000 at 2 percent)\n  a describe tool with three parameters" }, { "name": "tool_specs.md", "text": "TOOL SPECS\n\n  lot_area         length x width\n  price_per_sqft   price divided by the square feet\n  monthly_cost     rent + utilities + parking\n  listing          one sentence with the address and the bedrooms\n\nNOTE\n  arguments fill the parameters in the order they are given" } ], "review": { "open": "Thanks, I ran your tools on the sample listings.", "stages": [ { "ok": "The lot area and price per square foot tools are defined correctly.", "todo": "The first two tools aren't right yet: two parameters each, and the price divided by the square feet." }, { "ok": "The monthly cost adds all three numbers, and the listing sentence joins text and a number correctly.", "todo": "The monthly cost or the listing tool isn't right yet. The number has to be converted to join it." }, { "ok": "The page works, price per square foot is 200.0, and your ORDER note explains the swapped call.", "todo": "The listing page or the ORDER comment isn't done yet." }, { "ok": "The commission tool is right for both sales.", "todo": "Stretch: the commission tool isn't done yet. It's optional." }, { "ok": "The describe tool works with three parameters, and your ARGS note is correct.", "todo": "Stretch: the describe tool isn't done yet. Also optional." } ], "approve": "Every tool gives the right number.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "Agents have wanted the commission tool for a long time.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a153 = { "match": "Walmart Checkout Totals", "core": 3, "brand": { "name": "Walmart", "color": "#0071CE", "head": "#0071CE", "ink": "#ffffff", "team": "Checkout Systems", "font": "700 26px Arial,Helvetica,sans-serif", "spacing": "-0.5px" }, "boss": { "name": "Denise Parker", "title": "Checkout Systems Engineer", "initials": "DP" }, "ticket": "REG-4921", "file": "checkout_totals.py", "email": { "subject": "Register totals: functions that hand back an answer", "paras": [ "Hi, welcome to Checkout Systems!", "The register needs functions that **hand back** an answer, so the total for one item can be stored, added to other totals and passed into the next function. A function that only prints can't do that: it has to **return**. Please keep the functions together at the top and the register at the bottom.", "`register_cases.txt` has the baskets to test with, and `return_notes.md` explains the style we follow.", "Work through the steps below in order. When you have a version that runs, click **Send to Denise** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Denise" }, "files": [ { "name": "register_cases.txt", "text": "REGISTER CASES\n\n  3 shirts at 12 dollars\n  4 items at 5 dollars plus 10 items at 2 dollars\n  10 items at 10 dollars with 5 dollars shipping\n  a name tag for Sam Rivera\n  one item at 9 dollars (a price tag printer that only prints)\n\nSTRETCH TASKS\n  a 5 dollar coupon, and a 10 dollar coupon on a gift\n  10 percent tax on the grand total" }, { "name": "return_notes.md", "text": "RETURN NOTES\n\n  - a function that only prints gives back nothing\n  - a returned value can be stored, added or passed to another function\n  - a function stops at its return line" } ], "review": { "open": "Thanks, I rang up the test baskets with your functions.", "stages": [ { "ok": "item_total and add_shipping both return their answers.", "todo": "The first two functions aren't right yet: item_total and add_shipping must return, not print." }, { "ok": "make_tag returns the tag, your ENDS note is right, and show_price is the print-only version.", "todo": "make_tag, the ENDS comment or show_price isn't done yet." }, { "ok": "The register works: stored totals, a call inside a call, the tag, and your NONE note explains the None from show_price.", "todo": "The register isn't right yet, or the NONE comment is missing." }, { "ok": "Coupons work, including the nested call.", "todo": "Stretch: the coupons aren't done yet. It's optional." }, { "ok": "The tax function returns its answer, and your VALUE note is right.", "todo": "Stretch: the tax function isn't done yet. Also optional." } ], "approve": "Every total is correct.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The tax function is going into the register code.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a154 = { "match": "Duolingo Streak Rules", "core": 3, "brand": { "name": "duolingo", "color": "#58A700", "head": "#58CC02", "ink": "#ffffff", "team": "Learning Engine", "font": "900 26px 'Trebuchet MS',Arial,sans-serif", "spacing": "-1px" }, "boss": { "name": "Hye-jin Park", "title": "Learning Engine Engineer", "initials": "HP" }, "ticket": "LRN-7015", "file": "streak_rules.py", "email": { "subject": "Streak, league and XP rules", "paras": [ "Hi, welcome to the Learning Engine team!", "Streaks, leagues and XP bonuses are decided by functions that **make decisions and use loops, then return an answer**. Sometimes the answer is a True or False, sometimes one of two numbers, sometimes a label, and sometimes the result of a loop. Keep the rules together at the top and a sample learner's day at the bottom.", "`rules_table.txt` lists every rule, and `test_learners.md` has the learner to try.", "Work through the steps below in order. When you have a version that runs, click **Send to Hye-jin** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Hye-jin" }, "files": [ { "name": "rules_table.txt", "text": "RULES\n\n  Weekly bonus     every 7th day of a streak\n  Higher XP        the larger of two scores\n  League           500 XP or more Gold, 200 or more Silver, below that Bronze\n  XP for lessons   lesson 1 earns 1 XP, lesson 2 earns 2 XP, and so on\n  Bonus lessons    every even lesson number\n\nSTRETCH TASKS\n  a streak freeze for 10 gems or more\n  weekly XP: 10 XP on every 7th day" }, { "name": "test_learners.md", "text": "TEST LEARNER\n\n  a 14 day streak and a 7 day streak\n  scores of 40 and 55\n  350 XP\n  5 lessons, and 10 lessons\n  15 gems, and 5 gems\n  21 days" } ], "review": { "open": "Thanks, I tried your rules on the test learner.", "stages": [ { "ok": "is_streak_day returns True or False, and higher_xp returns the larger score.", "todo": "The first rules aren't right yet: is_streak_day returns whether days divide by 7, higher_xp returns a or b." }, { "ok": "league uses early returns, xp_for returns after its loop, and bonus_lessons counts only the even lessons.", "todo": "One of league, xp_for or bonus_lessons isn't right yet." }, { "ok": "The learner's day gives the right answers, and the function works inside an if.", "todo": "The calls aren't right yet: check each print and the if on is_streak_day." }, { "ok": "The streak freeze works with not.", "todo": "Stretch: the streak freeze isn't done yet. It's optional." }, { "ok": "Weekly XP is 30 for 21 days, and your AFTER note is right.", "todo": "Stretch: weekly XP isn't done yet. Also optional." } ], "approve": "Every rule returns the right answer.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The streak freeze rule goes to design review next week.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a155 = { "match": "Google Maps Distance Tools", "core": 3, "brand": { "name": "Google Maps", "color": "#1A73E8", "head": "#ffffff", "ink": "#1A73E8", "team": "Routing", "font": "700 24px Arial,Helvetica,sans-serif", "spacing": "-0.5px" }, "boss": { "name": "Ibrahim Hassan", "title": "Routing Engineer", "initials": "IH" }, "ticket": "RTE-5527", "file": "distance_tools.py", "email": { "subject": "Distance tools: use the libraries, don't reinvent them", "paras": [ "Hi, welcome to Routing!", "We don't write every tool from scratch. We use **libraries** other people built, and we read their documentation to learn what to type. The documentation is on the page: use it the way an engineer would, and then build one tool of your own on top of a library.", "`city_blocks.txt` has the test numbers, and `docs_quicklook.md` is a short reminder of how to read library documentation.", "Work through the steps below in order. When you have a version that runs, click **Send to Ibrahim** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Ibrahim" }, "files": [ { "name": "city_blocks.txt", "text": "TEST NUMBERS\n\n  a square plot of 144 square blocks\n  a trip 7 blocks west\n  3.14159 (to round)\n  the street Peachtree\n  a trip 3 blocks east and 4 blocks north, then 6 and 8\n\nSTRETCH TASKS\n  a rounded straight line for 2 east and 3 north\n  walking distance on a grid, with a random detour" }, { "name": "docs_quicklook.md", "text": "READING DOCUMENTATION\n\n  - the name tells you what the tool does\n  - the order of the arguments matters\n  - some libraries have to be brought in before you can use them\n  - imports and your own functions go at the top of the file" } ], "review": { "open": "Thanks, I ran your tools on the test trips.", "stages": [ { "ok": "Both libraries are brought in at the top and your hypotenuse tool is built on one of them.", "todo": "The setup isn't done yet: import math and random, then a hypotenuse function that returns the square root." }, { "ok": "The square root, abs, round and len all work as documented.", "todo": "One of sqrt, abs, round or len isn't right yet." }, { "ok": "Both powers come out right, the detour is a whole number from 1 to 5, and your tool returns 5.0 and 10.0.", "todo": "The powers, the detour or your hypotenuse calls aren't right yet. Check the order of the arguments in the documentation." }, { "ok": "The rounded route, the area and the walking blocks are right.", "todo": "Stretch: the rounded routes aren't done yet. It's optional." }, { "ok": "walking and detour_walk both work, and the detour changes the answer.", "todo": "Stretch: walking with a detour isn't done yet. Also optional." } ], "approve": "Every tool matches the documentation.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "The detour tool goes to the routing team for testing.", "changes": "Fix those and send it back, and I'll take another look." } };
  W.a156 = { "match": "Netflix Rating Rows", "core": 3, "brand": { "name": "NETFLIX", "color": "#B20710", "head": "#141414", "ink": "#E50914", "team": "Interface", "font": "900 24px 'Arial Black',Arial,sans-serif", "spacing": "3px" }, "boss": { "name": "Olivia Brandt", "title": "Interface Engineer", "initials": "OB" }, "ticket": "UI-9034", "file": "rating_rows.py", "email": { "subject": "Rating rows: remove the repetition", "paras": [ "Hi, welcome to the Interface team!", "Every row of titles shows a divider, a welcome message and a star rating, and the same few jobs repeat across thousands of screens. Good procedures remove repetition, take **parameters** to change what they do, and can call **each other**. These are the same pieces the AP Create Task needs, so this is good practice. Keep the procedures together at the top and the rows at the bottom.", "`row_layout.txt` shows what each row looks like, and `procedure_notes.md` has the standards we follow.", "Work through the steps below in order. When you have a version that runs, click **Send to Olivia** and I'll look it over and reply.", "If you finish early and want to take on more, there are two stretch tasks at the bottom. They're optional, but I notice the people who go the extra mile." ], "sign": "Thanks, Olivia" }, "files": [ { "name": "row_layout.txt", "text": "ROW LAYOUT\n\n  divider       ten dashes above and below a title\n  welcome       Welcome back, <name>   or   Welcome, <name>\n  stars         one star for every rating point\n  show_rating   the title, the stars, then Top rated at 4 or more, otherwise Keep watching\n\nSTRETCH TASKS\n  a title card that uses the divider\n  a message repeated 3 times" }, { "name": "procedure_notes.md", "text": "PROCEDURE NOTES\n\n  - a repeated job belongs in one procedure\n  - parameters change what a procedure does\n  - a procedure can call another procedure\n  - change the code in one place, not in a thousand" } ], "review": { "open": "Thanks, I ran your rows.", "stages": [ { "ok": "divider removes the repetition, and welcome changes with its parameters.", "todo": "divider or welcome isn't right yet: ten dashes, and a name and is_member with an if and an else." }, { "ok": "stars builds the right number of stars with a loop, and show_rating calls stars and decides between Top rated and Keep watching.", "todo": "stars or show_rating isn't right yet." }, { "ok": "The rows come out right, and your ONCE note explains exactly why one procedure beats copies.", "todo": "The rows or the ONCE comment isn't right yet." }, { "ok": "The title card uses the divider twice.", "todo": "Stretch: the title card isn't done yet. It's optional." }, { "ok": "repeat_message works, and your REUSE note is a good point.", "todo": "Stretch: repeat_message isn't done yet. Also optional." } ], "approve": "Every row on the screen works.", "moreStretch": "There are two stretch tasks at the bottom if you want to take them on.", "allDone": "Repeat message is going into the interface library.", "changes": "Fix those and send it back, and I'll take another look." } };
